CREATE TABLE text_shares(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,slug VARCHAR(64) NOT NULL,title VARCHAR(255) NOT NULL,content MEDIUMTEXT NOT NULL,format ENUM('plain','markdown','code') NOT NULL DEFAULT 'plain',password_hash VARCHAR(255) NULL,expires_at DATETIME NULL,one_time BOOLEAN NOT NULL DEFAULT FALSE,status ENUM('active','consumed','expired','paused') NOT NULL DEFAULT 'active',views BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),UNIQUE KEY text_shares_slug_unique(slug),KEY text_shares_workspace_status_idx(workspace_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bio_pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,slug VARCHAR(64) NOT NULL,title VARCHAR(255) NOT NULL,bio TEXT NULL,theme JSON NOT NULL,blocks JSON NOT NULL,status ENUM('draft','published','paused') NOT NULL DEFAULT 'draft',views BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),UNIQUE KEY bio_pages_slug_unique(slug),KEY bio_pages_workspace_status_idx(workspace_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE qr_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,link_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,image_url VARCHAR(500) NOT NULL,foreground CHAR(7) NOT NULL DEFAULT '#10233f',background CHAR(7) NOT NULL DEFAULT '#ffffff',size INT UNSIGNED NOT NULL DEFAULT 1024,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE CASCADE,KEY qr_workspace_created_idx(workspace_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE file_shares(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,slug VARCHAR(64) NOT NULL,original_name VARCHAR(255) NOT NULL,storage_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,scan_status ENUM('pending','clean','infected','error') NOT NULL DEFAULT 'pending',scan_result TEXT NULL,status ENUM('active','quarantined','expired','paused') NOT NULL DEFAULT 'quarantined',expires_at DATETIME NULL,max_downloads BIGINT UNSIGNED NULL,downloads BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),UNIQUE KEY file_shares_slug_unique(slug),KEY file_workspace_scan_idx(workspace_id,scan_status,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
